 "content": "def transform(grid):
    # The solid 5 row separates two patterns. Select the color whose
    # vertical mark count increases more from the upper region to lower.
    divider = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    top, bottom = grid[:divider], grid[divider + 1:]
    colors = {v for row in grid for v in row if v not in (0, 5)}
    def count(rows, color):
        return sum(v == color for row in rows for v in row)
    color = max(colors, key=lambda c: count(bottom, c) - count(top, c))
    return [[color, color], [color, color]]
